{"command": "cd /workspace && python3 <<'PY' > /tmp/infer.py
import subprocess, os, shutil, json

# get langs
text=open("/tmp/langs.txt",encoding="utf-8").read()
langs=[]
for line in text.splitlines()[3:-1]:
    if line.startswith("━") or "Language" in line:
        continue
    inner=line[2:-2]
    lang=inner[:38].strip()
    exts=inner[38:].strip()
    first_ext=exts.split(",")[0].strip().split()[0].replace("...","") if exts else ""
    if not first_ext:
        continue
    langs.append((lang, first_ext))

print(f"langs {len(langs)}")

# candidates
line_candidates=["#", "//", "--", ";", "%", "!", "*", "'", '"', ":", ">", "|", "REM", "rem"]
block_candidates=[("/*","*/"), ("<!--","-->"), ("{-","-}"), ("(*","*)"), ("--[[","--]]"), ("\"\"\"","\"\"\""), ("'''","'''"), ("=begin","=end"), ("#=","=#")]

def cnt(ext, content):
    shutil.rmtree("/tmp/cnt", ignore_errors=True)
    os.makedirs("/tmp/cnt", exist_ok=True)
    open(f"/tmp/cnt/a.{ext}","w").write(content)
    r=subprocess.run(["/workspace/executable","/tmp/cnt","-o","json"], capture_output=True)
    try:
        j=json.loads(r.stdout.decode())
    except:
        return None
    for k,v in j.items():
        if k!="Total":
            return (v['code'], v['comments'], v['blanks'])
    return (0,0,0)

# test a few
for lang, ext in langs[:5]:
    print(f"=== {lang} {ext} ===")
    for lc in ["#","//","--",";"]:
        res=cnt(ext, f"{lc} comment\n")
        print(f"  line {lc!r} => {res}")
    for bstart, bend in [("/*","*/"), ("<!--","-->")]:
        res=cnt(ext, f"{bstart} comment {bend}\n")
        print(f"  block {bstart} {bend} => {res}")

PY
cat /tmp/infer.py"}

