import subprocess, os, shutil, json
text=open("/tmp/langs.txt",encoding="utf-8").read()
langs=[]
for line in text.splitlines()[3:-1]:
    if line.startswith("━") or "Language" in line:
        continue
    inner=line[2:-2]
    lang=inner[:38].strip()
    exts=inner[38:].strip()
    first_ext=exts.split(",")[0].strip().split()[0].replace("...","") if exts else ""
    if not first_ext or "." in first_ext or first_ext in ["..."]:
        continue
    # skip weird exts like 🍇, MAC etc? need to handle
    langs.append((lang, first_ext))
print(f"total {len(langs)}")

def cnt(ext, content):
    shutil.rmtree("/tmp/cnt", ignore_errors=True)
    os.makedirs("/tmp/cnt", exist_ok=True)
    try:
        open(f"/tmp/cnt/a.{ext}","w").write(content)
    except Exception as e:
        return None
    r=subprocess.run(["/workspace/executable","/tmp/cnt","-o","json"], capture_output=True)
    try:
        j=json.loads(r.stdout.decode())
    except:
        return None
    for k,v in j.items():
        if k!="Total":
            return (v['code'], v['comments'])
    return (0,0)

# quick test for all langs with # and // and /* */
for lang, ext in langs:
    # skip problematic exts
    if len(ext)>10 or ext=="":
        continue
    r1=cnt(ext, "# comment\n")
    r2=cnt(ext, "// comment\n")
    r3=cnt(ext, "/* comment */\n")
    print(f"{lang}|{ext}|#:{r1}|//:{r2}|/**/:{r3}")
PY"}

