# ---------- Language detection ----------
def detect_language(filepath):
    basename = os.path.basename(filepath)
    lower_base = basename.lower()
    if lower_base in FILENAME_MAP:
        return FILENAME_MAP[lower_base]
    if "." in basename:
        ext = basename.rsplit(".", 1)[-1].lower()
        if ext == "":
            return None
        if ext in EXT_MAP:
            return EXT_MAP[ext]
        else:
            return None
    else:
        # No dot: try shebang
        try:
            with open(filepath, 'rb') as f:
                first = f.readline(2048)
                try:
                    line = first.decode('utf-8', errors='ignore')
                except:
                    return None
                if line.startswith("#!"):
                    if len(line) > 2 and line[2] in (' ', '\t'):
                        return None
                    rest = line[2:].strip()
                    if not rest:
                        return None
                    # remove trailing newline etc.
                    rest = rest.strip()
                    parts = rest.split()
                    if not parts:
                        return None
                    path = parts[0]
                    interp = os.path.basename(path)
                    if interp == "env":
                        if len(parts) < 2:
                            return None
                        interp = os.path.basename(parts[1])
                    low = interp.lower()
                    stripped = re.sub(r'[0-9\.\-]+$', '', low)
                    candidates = [low] if stripped == low else [low, stripped]
                    for cand in candidates:
                        if not cand:
                            continue
                        if cand in LANG_NAMES_LOWER:
                            return LANG_NAMES_LOWER[cand]
                        if cand in EXT_MAP:
                            return EXT_MAP[cand]
                    return None
                else:
                    return None
        except Exception:
            return None
        return None
    return None

def get_lang_info(lang):
    return LANG_DEFS.get(lang, {"line": [], "block": [], "nested": False, "is_comment_all": False})

# Generic counting for list of lines
def count_generic_lines(lines, lang):
    info = get_lang_info(lang)
    line_comments = info.get("line", [])
    block_comments = info.get("block", [])
    nested = info.get("nested", False)
    is_comment_all = info.get("is_comment_all", False)
    if is_comment_all:
        blanks=code=comments=0
        for line in lines:
            if line.strip() == "":
                blanks+=1
            else:
                comments+=1
        return {"blanks": blanks, "code": code, "comments": comments, "blobs": {}}
    line_sorted = sorted(line_comments, key=len, reverse=True)
    bmap = {}
    for s,e in block_comments:
        bmap[s]=e
    bstarts_sorted = sorted(bmap.keys(), key=len, reverse=True)
    quotes = [q for q in ['"', "'", "`"] if q not in line_comments]
    blanks=code=comments=0
    in_block=[]  # stack of ends
    in_str=None
    for line in lines:
        stripped = line.strip()
        if stripped=="":
            if in_block:
                comments+=1
            else:
                if in_str is not None:
                    code+=1
                else:
                    blanks+=1
            continue
        if in_block:
            # starts inside block => comment, update state
            idx=0
            # parse to update in_block
            while idx < len(line):
                if in_block and line.startswith(in_block[-1], idx):
                    e = in_block.pop()
                    idx+=len(e)
                    continue
                if nested:
                    found=None
                    for s in bstarts_sorted:
                        if line.startswith(s, idx):
                            found=s
                            break
                    if found is not None:
                        in_block.append(bmap[found])
                        idx+=len(found)
                        continue
                idx+=1
            in_str=None
            comments+=1
            continue
        # not in block at start
        has_code=False
        has_comment=False
        idx=0
        # if in_str from prev line, has_code already? Will be detected via parsing (since in_str)
        while idx < len(line):
            if in_str is not None:
                if line[idx]=='\\' and idx+1 < len(line):
                    has_code=True
                    idx+=2
                    continue
                if line.startswith(in_str, idx):
                    has_code=True
                    idx+=len(in_str)
                    in_str=None
                    continue
                else:
                    has_code=True
                    idx+=1
                    continue
            if in_block:
                top=in_block[-1]
                if line.startswith(top, idx):
                    in_block.pop()
                    has_comment=True
                    idx+=len(top)
                    continue
                if nested:
                    f=None
                    for s in bstarts_sorted:
                        if line.startswith(s, idx):
                            f=s
                            break
                    if f is not None:
                        in_block.append(bmap[f])
                        has_comment=True
                        idx+=len(f)
                        continue
                has_comment=True
                idx+=1
                continue
            # check line comments
            fl=None
            for lc in line_sorted:
                if line.startswith(lc, idx):
                    fl=lc
                    break
            if fl is not None:
                has_comment=True
                break
            # check block starts
            fb=None
            for s in bstarts_sorted:
                if line.startswith(s, idx):
                    fb=s
                    break
            if fb is not None:
                in_block.append(bmap[fb])
                has_comment=True
                idx+=len(fb)
                continue
            # check quotes
            fq=None
            for q in quotes:
                if line.startswith(q, idx):
                    fq=q
                    break
            if fq is not None:
                in_str=fq
                has_code=True
                idx+=len(fq)
                continue
            ch=line[idx]
            if ch.isspace():
                idx+=1
                continue
            else:
                has_code=True
                idx+=1
                continue
        if has_code:
            code+=1
        elif has_comment:
            comments+=1
        else:
            code+=1
    return {"blanks": blanks, "code": code, "comments": comments, "blobs": {}}

def count_markdown_lines(lines):
    blanks=0
    comments=0
    code=0
    blobs={}
    embedded={}  # lang -> list
    in_fence=False
    fence_lang=None
    for line in lines:
        if "```" in line:
            if not in_fence:
                idx=line.find("```")
                rest=line[idx+3:]
                if rest=="" or (rest and rest[0] in (' ', '\t')):
                    in_fence=True
                    fence_lang=None
                else:
                    token=rest.strip().split()[0] if rest.strip() else ""
